      function update(){const el=document.querySelector('#crossing-cat');el.style.left=(player.x+.5)/5*100+'%';el.style.top=(player.y+.5)/7*100+'%';if(!started)return;const traffic=cars();document.querySelector('#crossing-cars').innerHTML=traffic.map(car=>`<span style="left:${(car.x+.5)/5*100}%;top:${(car.y+.5)/7*100}%;transform:translate(-50%,-50%) rotate(${lanes[car.k].speed>0?90:-90}deg)">${icon('car',car.k)}</span>`).join('');if(!stunned&&traffic.some(car=>car.y===player.y&&Math.abs(car.x-player.x)<.58)){stunned=true;crashes++;el.classList.add('bumped');later(()=>{player={x:2,y:6};stunned=false;el.classList.remove('bumped');update();},650);status('Осторожно! Попробуйте пройти между машинами.');}}
